UPDATE  /* isry.couns.constt.chttmng.mapper.InqLobbyListMapper.deleteLobby : 채팅내역 게시글삭제 */
        AYB260 
SET
        DEL_YN                  =       'Y'
    ,   LAST_MDFCN_DT           =       SYSDATE      
    ,   LAST_MDFR_ID            =       #{LAST_MDFR_ID}    
WHERE   1=1

    AND     CHTT_LOG_ESNTAL_NO  =       #{CHTT_LOG_ESNTAL_NO}


    AND     CLIENA_ID           =       #{CLIENA_ID}
    AND     DEL_YN              =       'N'
